import {Strings} from "@openzeppelin/contracts/utils/Strings.sol";
import {IERC721} from "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";

import {UriUtils} from "./libraries/UriUtils.sol";
import {KeyValue} from "./types/KeyValue.sol";
import {IAgentCollectionStates} from "./interfaces/IAgentCollection/IAgentCollectionStates.sol";
import {IAgentCollectionsDescriptor} from "./interfaces/IAgentCollectionsDescriptor/IAgentCollectionsDescriptor.sol";

/// @title Descriptor for Agentic AI collections
/// @dev Provides token metadata generation and stores IPFS gateway information.
contract AgentCollectionsDescriptor is
    AccessControl,
    IAgentCollectionsDescriptor
{
    using Strings for uint256;

    string private _ipfsGateway;

    /// @dev Create a new descriptor instance.
    /// @param ipfsGateway Initial IPFS gateway URL used for images.
    constructor(string memory ipfsGateway) {
        _ipfsGateway = ipfsGateway;
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
    }

    /// @dev Update the IPFS gateway used to resolve images.
    /// @param ipfsGateway The new IPFS gateway URL.
    function updateIpfsGateway(string memory ipfsGateway) external onlyRole(DEFAULT_ADMIN_ROLE) {
        string memory oldGateway = _ipfsGateway;
        _ipfsGateway = ipfsGateway;
        emit IpfsGatewayUpdated(oldGateway, ipfsGateway);
    }

    /// @dev Build the ERC721 token URI for a specific token.
    /// @param collection The collection address.
    /// @param tokenId The token identifier.
    /// @return The metadata URI.
    function buildTokenURI(
        address collection,
        uint256 tokenId
    ) external view returns (string memory) {
        IAgentCollectionStates collectionStates = IAgentCollectionStates(collection);

        string memory description = _escapeJSON(collectionStates.description());

        string memory agentName = _escapeJSON(collectionStates.nameOf(tokenId));

        string memory defaultImage = _getDefaultImage(collectionStates, tokenId);
        string memory defaultImageUrl = _escapeJSON(_generateImageUrl(defaultImage));

        return
            string(
                abi.encodePacked(
                    "data:application/json;base64,",
                    Base64.encode(
                        bytes(
                            abi.encodePacked(
                                '{"name":"',
                                agentName,
                                '", "description":"',
                                description,
                                '", "image": "',
                                defaultImageUrl,
                                '"}'
                            )
                        )
                    )
                )
            );
    }

    /// @dev Escape a string for safe inclusion inside a JSON string literal:
    ///      backslash-escape `"` and `\`, use short escapes for `\b \t \n \f \r`,
    ///      and `\u00XX` for any other control character < 0x20 (RFC 8259).
    ///      Applied to all dynamic values (name, description, image URL) so an
    ///      attacker- or moderator-controlled value cannot break out of — or
    ///      produce invalid — the metadata JSON.
    function _escapeJSON(
        string memory value
    ) internal pure returns (string memory) {
        bytes memory valueBytes = bytes(value);
        uint256 extraCount = 0;
        for (uint256 i = 0; i < valueBytes.length; i++) {
            uint8 c = uint8(valueBytes[i]);
            if (c == 0x22 || c == 0x5c) {
                extraCount += 1;
            } else if (c == 0x08 || c == 0x09 || c == 0x0a || c == 0x0c || c == 0x0d) {
                extraCount += 1;
            } else if (c < 0x20) {
                extraCount += 5;
            }
        }
        if (extraCount == 0) {
            return value;
        }

        bytes memory hexDigits = "0123456789abcdef";
        bytes memory escapedBytes = new bytes(valueBytes.length + extraCount);
        uint256 index;
        for (uint256 i = 0; i < valueBytes.length; i++) {
            uint8 c = uint8(valueBytes[i]);
            if (c == 0x22 || c == 0x5c) {
                escapedBytes[index++] = "\\";
                escapedBytes[index++] = valueBytes[i];
            } else if (c == 0x08) {
                escapedBytes[index++] = "\\";
                escapedBytes[index++] = "b";
            } else if (c == 0x09) {
                escapedBytes[index++] = "\\";
                escapedBytes[index++] = "t";
            } else if (c == 0x0a) {
                escapedBytes[index++] = "\\";
                escapedBytes[index++] = "n";
            } else if (c == 0x0c) {
                escapedBytes[index++] = "\\";
                escapedBytes[index++] = "f";
            } else if (c == 0x0d) {
                escapedBytes[index++] = "\\";
                escapedBytes[index++] = "r";
            } else if (c < 0x20) {
                escapedBytes[index++] = "\\";
                escapedBytes[index++] = "u";
                escapedBytes[index++] = "0";
                escapedBytes[index++] = "0";
                escapedBytes[index++] = hexDigits[c >> 4];
                escapedBytes[index++] = hexDigits[c & 0x0f];
            } else {
                escapedBytes[index++] = valueBytes[i];
            }
        }
        return string(escapedBytes);
    }

    /// @dev Retrieve the default image from the image list.
    ///      Reverts if no image with key `default` is found.
    function _getDefaultImage(IAgentCollectionStates collectionStates, uint256 tokenId) internal view returns (string memory) {
        string memory defaultImage = "";

        uint256 countOfImages = collectionStates.imagesCountOf(tokenId);

        for (uint256 i = 0; i < countOfImages; i++) {
            KeyValue memory images = collectionStates.imageOfByIndex(tokenId, i);

            if (
                keccak256(abi.encodePacked(images.key)) == keccak256(abi.encodePacked("default"))
            ) {
                defaultImage = images.value;
                break;
            }
        }

        if (keccak256(abi.encodePacked(defaultImage)) == keccak256(abi.encodePacked(""))) {
            revert MissingDefaultImage();
        }

        return defaultImage;
    }

    /// @dev Concatenate the gateway with the image hash to form an URL.
    ///      Values that already carry a scheme pass through untouched.
    function _generateImageUrl(
        string memory image
    ) internal view returns (string memory) {
        return UriUtils.prefixUnlessUri(_ipfsGateway, image);
    }
}

contracts/AgentCollectionsManager.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.28;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {IERC721Metadata} from "@openzeppelin/contracts/token/ERC721/extensions/IERC721Metadata.sol";

import {IAgentCollectionStates} from "./interfaces/IAgentCollection/IAgentCollectionStates.sol";
import {IAgentCollectionsManager} from "./interfaces/IAgentCollectionsManager/IAgentCollectionsManager.sol";
import {AgentCollectionInfo} from "./types/AgentCollectionInfo.sol";

/// @title Agentic AI collections manager
/// @dev Manages collections and authorizes creators.
contract AgentCollectionsManager is
    AccessControl,
    IAgentCollectionsManager
{
    bytes32 public constant CREATOR_ROLE = keccak256("CREATOR_ROLE");

    uint256 public nextCollectionId = 1;

    mapping(uint256 => address) public collections;
    mapping(string => uint256) public collectionIdByName;
    mapping(string => uint256) public collectionIdBySymbol;
    mapping(address => bool) public isKnownCollection;

    /// @dev Deploy the manager and set the deployer as admin.
    constructor() {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
    }

    function moderatorOf(address account) external view returns (address[] memory) {
        uint256 numberOfModeratorCollections = 0;

        // Count the number of collections where the account is a moderator
        for (uint256 collectionIndex = 1; collectionIndex < nextCollectionId; collectionIndex++) {
            IAgentCollectionStates collection = IAgentCollectionStates(collections[collectionIndex]);
            if (collection.isModerator(account)) {
                numberOfModeratorCollections++;
            }
        }

        // Fill the array with the addresses of the collections where the account is a moderator
        address[] memory moderatorCollections = new address[](numberOfModeratorCollections);
        uint256 insertIndex = 0;
        for (uint256 collectionIndex = 1; collectionIndex < nextCollectionId; collectionIndex++) {
            address collection = collections[collectionIndex];
            if (IAgentCollectionStates(collection).isModerator(account)) {
                moderatorCollections[insertIndex] = collection;
                insertIndex++;
            }
        }

        return moderatorCollections;
    }

    /// @dev Paginated collection listing for the operator UI. Pass offset 0 to
    /// start; `next` is the id to resume from, or 0 when exhausted.
    function listCollections(
        uint256 offset,
        uint256 limit
    ) external view returns (AgentCollectionInfo[] memory infos, uint256 next) {
        uint256 start = offset < 1 ? 1 : offset;
        uint256 end = start + limit;
        if (end > nextCollectionId) {
            end = nextCollectionId;
        }
        uint256 count = end > start ? end - start : 0;

        infos = new AgentCollectionInfo[](count);
        for (uint256 i = 0; i < count; i++) {
            address collection = collections[start + i];
            IAgentCollectionStates state = IAgentCollectionStates(collection);
            infos[i] = AgentCollectionInfo({
                collectionAddress: collection,
                name: IERC721Metadata(collection).name(),
                description: state.description(),
                moderatorCount: state.moderatorCount(),
                nextTokenId: state.nextTokenId()
            });
        }
        next = end < nextCollectionId ? end : 0;
    }

    /// @dev Paginated search for the agent a typed address belongs to. Returns
    /// the first match in [offset, offset+limit) or zeros; `next` resumes the scan.
    function findAgentByAddress(
        string memory addressType,
        string memory value,
        uint256 offset,
        uint256 limit
    ) external view returns (address collection, uint256 tokenId, string memory name, uint256 next) {
        uint256 start = offset < 1 ? 1 : offset;
        uint256 end = start + limit;
        if (end > nextCollectionId) {
            end = nextCollectionId;
        }

        for (uint256 id = start; id < end; id++) {
            address current = collections[id];
            uint256 foundTokenId = IAgentCollectionStates(current).addressToTokenId(addressType, value);
            if (foundTokenId != 0) {
                return (current, foundTokenId, IAgentCollectionStates(current).nameOf(foundTokenId), 0);
            }
        }

        next = end < nextCollectionId ? end : 0;
        return (address(0), 0, "", next);
    }

    /// @dev Add a new collection.
    /// @param newCollection The new collection to add.
    function addCollection(
        address newCollection
    ) external onlyRole(CREATOR_ROLE) {
        string memory name = IERC721Metadata(newCollection).name();
        string memory symbol = IERC721Metadata(newCollection).symbol();

        if (collectionIdByName[name] != 0) {
            revert CollectionNameAlreadyExists(name);
        }
        if (collectionIdBySymbol[symbol] != 0) {
            revert CollectionSymbolAlreadyExists(symbol);
        }

        collections[nextCollectionId] = address(newCollection);
        collectionIdByName[name] = nextCollectionId;
        collectionIdBySymbol[symbol] = nextCollectionId;
        isKnownCollection[address(newCollection)] = true;

        emit CollectionCreated(
            nextCollectionId,
            address(newCollection),
            name,
            symbol
        );

        nextCollectionId++;
    }
}

contracts/AgentCollectionV1.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.28;

import {IERC165} from "@openzeppelin/contracts/utils/introspection/IERC165.sol";
import {IERC721Metadata} from "@openzeppelin/contracts/token/ERC721/extensions/IERC721Metadata.sol";
import {Strings} from "@openzeppelin/contracts/utils/Strings.sol";

import {ERC721Upgradeable} from "@openzeppelin/contracts-upgradeable/token/ERC721/ERC721Upgradeable.sol";
import {AccessControlUpgradeable} from "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";

import {ENSUtils} from "./libraries/ENSUtils.sol";
import {KeyValueLib} from "./libraries/KeyValueLib.sol";
import {AgentAddressLib} from "./libraries/AgentAddressLib.sol";

import {KeyValue} from "./types/KeyValue.sol";
import {NullableUint256} from "./types/NullableUint256.sol";
import {AgentInformation} from "./types/AgentInformation.sol";
import {AgentAddress, EVM_TYPE} from "./types/AgentAddress.sol";
import {IAgentCollectionV1} from "./interfaces/IAgentCollectionV1/IAgentCollectionV1.sol";
import {IAgentCollectionsDescriptorActions} from "./interfaces/IAgentCollectionsDescriptor/IAgentCollectionsDescriptorActions.sol";

struct MintProposal {
    uint256 id;
    string name;
    string role;
    address owner;
    address creator;
    KeyValue[] images;
    KeyValue[] attributes;
    NullableUint256 cloneOf;
    AgentAddress[] addresses;
}

struct AddOrUpdateAgentImageProposal {
    uint256 id;
    uint256 tokenId;
    KeyValue image;
}

/// @title Agentic AI agent NFT collection
/// @dev ERC721 collection that supports off-chain minting proposals and image management.
contract AgentCollectionV1 is
    ERC721Upgradeable,
    AccessControlUpgradeable,
    IAgentCollectionV1
{
    using KeyValueLib for KeyValue[];
    using AgentAddressLib for AgentAddress;
    using AgentAddressLib for AgentAddress[];

    bytes32 public constant MODERATOR_ROLE = keccak256("MODERATOR_ROLE");

    mapping(string => uint256) private _nameToTokenId;
    mapping(string => mapping(string => uint256)) private _addressToTokenId;
    mapping(uint256 => AgentInformation) private _agentInformationOf;

    uint256 private _nextProposalId;

    MintProposal[] private _mintProposals;
    mapping(uint256 => uint256) private _mintProposalIndexById;

    AddOrUpdateAgentImageProposal[] private _addOrUpdateAgentImageProposals;
    mapping(uint256 => uint256) private _addOrUpdateAgentImageProposalIndexById;
    mapping(uint256 => mapping(bytes32 => uint256)) private _imageProposalIdByTokenAndKey;

    string public description;
    uint256 public moderatorCount;
    uint256 public nextTokenId;

    address public collectionsDescriptor;

    constructor() {
        _disableInitializers();
    }

    /// @dev Reverts if the caller is neither the agent owner nor one of its evm addresses.
    modifier onlyAgentController(uint256 tokenId) {
        if (!_isAgentController(tokenId, _msgSender())) {
            revert OwnableUnauthorizedAccount(_msgSender(), tokenId);
        }
        _;
    }

    /// @dev Reverts if the caller is neither an agent controller (owner or
    /// wallet) nor a moderator.
    modifier onlyAgentControllerOrModerator(uint256 tokenId) {
        if (!_isAgentController(tokenId, _msgSender()) && !hasRole(MODERATOR_ROLE, _msgSender())) {
            revert OwnableUnauthorizedAccount(_msgSender(), tokenId);
        }
        _;
    }

    /// @dev Reverts if there is no moderator set.
    modifier onlyWhenModeratorsExist() {
        if (moderatorCount == 0) {
            revert NoModerators();
        }
        _;
    }

    /// @dev Reverts if there is a moderator set and the caller is not one.
    modifier onlyWhenNoModeratorsOrSenderIsModerator() {
        if (moderatorCount > 0 && !hasRole(MODERATOR_ROLE, _msgSender())) {
            revert NotModerator(_msgSender());
        }
        _;
    }

    /// @dev Initialize a new agent collection.
    /// @param name ERC721 name of the collection.
    /// @param symbol ERC721 symbol of the collection.
    /// @param admin Address granted the default admin role.
    /// @param moderator Address granted the moderator role.
    /// @param initialCollectionsDescriptor Address of the descriptor contract.
    function initialize(
        string memory name,
        string memory symbol,
        string memory initialDescription,
        address admin,
        address moderator,
        address initialCollectionsDescriptor
    ) external initializer {
        if (!ENSUtils.isValidENSName(name)) {
            revert InvalidCollectionName(name);
        }
        if (admin == address(0)) {
            revert ZeroAddress("admin");
        }
        if (moderator == address(0)) {
            revert ZeroAddress("moderator");
        }
        if (initialCollectionsDescriptor == address(0)) {
            revert ZeroAddress("initialCollectionsDescriptor");
        }

        collectionsDescriptor = initialCollectionsDescriptor;

        nextTokenId = 1;
        description = initialDescription;

        _nextProposalId = 1;

        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(MODERATOR_ROLE, moderator);

        __ERC721_init(name, symbol);
        __AccessControl_init();
    }

    /// @dev See {AccessControl-_grantRole}. Only adjusts the moderator count on
    /// an actual change so redundant grants don't desync it.
    function _grantRole(bytes32 role, address account) internal override returns (bool) {
        bool granted = super._grantRole(role, account);
        if (granted && role == MODERATOR_ROLE) {
            moderatorCount++;
        }
        return granted;
    }

    /// @dev See {AccessControl-_revokeRole}. Only adjusts the moderator count on
    /// an actual change so spurious revokes don't desync (or underflow) it.
    function _revokeRole(bytes32 role, address account) internal override returns (bool) {
        bool revoked = super._revokeRole(role, account);
        if (revoked && role == MODERATOR_ROLE) {
            moderatorCount--;
        }
        return revoked;
    }

    /// @dev Get the fact that a account is a moderator or not.
    function isModerator(address account) external view returns (bool) {
        return hasRole(MODERATOR_ROLE, account);
    }

    /// @dev See {IERC165-supportsInterface}.
    function supportsInterface(
        bytes4 interfaceId
    )
        public
        view
        virtual
        override(ERC721Upgradeable, IERC165, AccessControlUpgradeable)
        returns (bool)
    {
        return
            ERC721Upgradeable.supportsInterface(interfaceId) ||
            AccessControlUpgradeable.supportsInterface(interfaceId);
    }

    /// @dev Update the descriptor contract used for metadata.
    /// @param newCollectionsDescriptor Address of the new descriptor contract.
    function updateCollectionsDescriptor(
        address newCollectionsDescriptor
    ) external onlyRole(MODERATOR_ROLE) {
        address oldDescriptor = address(collectionsDescriptor);

        collectionsDescriptor = newCollectionsDescriptor;

        emit CollectionsDescriptorUpdated(oldDescriptor, newCollectionsDescriptor);
    }

    /// @dev Update the collection description.
    /// @param newDescription The new description of the collection.
    function updateDescription(
        string memory newDescription
    ) external onlyRole(MODERATOR_ROLE) {
        string memory oldDescription = description;
        description = newDescription;

        emit DescriptionUpdated(oldDescription, newDescription);
    }

    /// @dev Return the token URI as defined by the descriptor contract.
    /// @param tokenId The token identifier.
    function tokenURI(
        uint256 tokenId
    ) public view override(ERC721Upgradeable, IERC721Metadata) returns (string memory) {
        _requireMinted(tokenId);

        return IAgentCollectionsDescriptorActions(collectionsDescriptor).
            buildTokenURI(address(this), tokenId);
    }

    /// @dev Get all stored information for an agent.
    /// @param tokenId The token identifier.
    /// @return The agent information structure.
    function informationOf(
        uint256 tokenId
    ) external view returns (AgentInformation memory) {
        _requireMinted(tokenId);

        return _agentInformationOf[tokenId];
    }

    /// @dev Get the creator address of an agent.
    /// @param tokenId The token identifier.
    function creatorOf(uint256 tokenId) external view returns (address) {
        _requireMinted(tokenId);

        return _agentInformationOf[tokenId].creator;
    }

    /// @dev Get the role of an agent
    /// @param tokenId The token identifier.
    function roleOf(uint256 tokenId) external view returns (string memory) {
        _requireMinted(tokenId);

        return _agentInformationOf[tokenId].role;
    }

    /// @dev Get the name of an agent
    /// @param tokenId The token identifier.
    function nameOf(uint256 tokenId) external view returns (string memory) {
        _requireMinted(tokenId);

        return _agentInformationOf[tokenId].name;
    }

    /// @dev Get the number of images of an agent.
    /// @param tokenId The token identifier.
    function imagesCountOf(uint256 tokenId) external view returns (uint256) {
        _requireMinted(tokenId);

        return _agentInformationOf[tokenId].images.length;
    }

    /// @dev Get a specific image of an agent by its index.
    /// @param tokenId The token identifier.
    /// @param index The index of the image.
    function imageOfByIndex(uint256 tokenId, uint256 index) external view returns (KeyValue memory) {
        _requireMinted(tokenId);

        return _agentInformationOf[tokenId].images[index];
    }

    /// @dev Get the number of typed addresses of an agent.
    /// @param tokenId The token identifier.
    function addressesCountOf(uint256 tokenId) external view returns (uint256) {
        _requireMinted(tokenId);

        return _agentInformationOf[tokenId].addresses.length;
    }

    /// @dev Get a specific typed address of an agent by its index.
    /// @param tokenId The token identifier.
    /// @param index The index of the address.
    function addressOfByIndex(uint256 tokenId, uint256 index) external view returns (AgentAddress memory) {
        _requireMinted(tokenId);

        return _agentInformationOf[tokenId].addresses[index];
    }

    /// @dev Get the number of attributes of an agent.
    /// @param tokenId The token identifier.
    function attributesCountOf(uint256 tokenId) external view returns (uint256) {
        _requireMinted(tokenId);

        return _agentInformationOf[tokenId].attributes.length;
    }

    /// @dev Get a specific attribute of an agent by its index.
    /// @param tokenId The token identifier.
    /// @param index The index of the attribute.
    function attributeOfByIndex(uint256 tokenId, uint256 index) external view returns (KeyValue memory) {
        _requireMinted(tokenId);

        return _agentInformationOf[tokenId].attributes[index];
    }

    /// @dev Get the token ID associated to the agent name.
    /// @param name The name of the agent.
    function nameToTokenId(string memory name) external view returns (uint256) {
        return _nameToTokenId[name];
    }

    /// @dev Get the token ID associated to a typed address, or 0 if none.
    /// @param addressType The type of the address ("evm", "btc", ...).
    /// @param value The address value (evm values accepted in any casing).
    function addressToTokenId(string memory addressType, string memory value) external view returns (uint256) {
        if (Strings.equal(addressType, EVM_TYPE)) {
            (bool success, address parsed) = Strings.tryParseAddress(value);
            if (success) {
                value = Strings.toHexString(parsed);
            }
        }
        return _addressToTokenId[addressType][value];
    }

    /// @dev Number of pending mint proposals.
    function mintProposalsLength() external view returns (uint256) {
        return _mintProposals.length;
    }

    /// @dev Get a mint proposal by index.
    /// @param proposalIndex Index of the proposal.
    function mintProposal(uint256 proposalIndex) external view returns (MintProposal memory) {
        return _mintProposals[proposalIndex];
    }

    /// @dev Number of pending image proposals.
    function addOrUpdateAgentImageProposalsLength() external view returns (uint256) {
        return _addOrUpdateAgentImageProposals.length;
    }

    /// @dev Get an image proposal by index.
    /// @param proposalIndex Index of the proposal.
    function addOrUpdateAgentImageProposal(uint256 proposalIndex) external view returns (AddOrUpdateAgentImageProposal memory) {
        return _addOrUpdateAgentImageProposals[proposalIndex];
    }

    /// @dev Add the attribute key/value pair to a token. If the key already exists, its value is updated.
    /// @param tokenId The token whose attribute key is updated.
    /// @param key The attribute key to update.
    /// @param value The new value for the attribute key.
    function addOrUpdateAgentAttribute(
        uint256 tokenId,
        string memory key,
        string memory value
    ) external onlyAgentController(tokenId) {
        AgentInformation storage agentInfo = _agentInformationOf[tokenId];

        string memory oldValue = agentInfo.attributes.addOrUpdate(key, value);
        emit AgentAttributeUpdated(
            tokenId,
            key,
            oldValue,
            value
        );
    }

    /// @dev Add a typed address to an agent (agent controller only).
    function addAgentAddress(
        uint256 tokenId,
        string memory addressType,
        string memory value
    ) external onlyAgentController(tokenId) {
        (AgentAddress memory canonical, ) =
            AgentAddress({
                addressType: addressType,
                value: value
            }).validateAndCanonicalize();

        uint256 tokenIdForAddress = _addressToTokenId[canonical.addressType][canonical.value];
        if (tokenIdForAddress != 0) {
            revert UsedAgentAddress(canonical.addressType, canonical.value, tokenIdForAddress);
        }

        _agentInformationOf[tokenId].addresses.push(canonical);
        _addressToTokenId[canonical.addressType][canonical.value] = tokenId;

        emit AgentAddressAdded(tokenId, canonical.addressType, canonical.value);
    }

    /// @dev Remove a typed address from an agent (agent controller only).
    function removeAgentAddress(
        uint256 tokenId,
        string memory addressType,
        string memory value
    ) external onlyAgentController(tokenId) {
        (AgentAddress memory canonical, ) =
            AgentAddress({
                addressType: addressType,
                value: value
            }).validateAndCanonicalize();

        if (_addressToTokenId[canonical.addressType][canonical.value] != tokenId) {
            revert AgentAddressNotFound(canonical.addressType, canonical.value);
        }

        AgentAddress[] storage addresses = _agentInformationOf[tokenId].addresses;
        uint256 length = addresses.length;
        for (uint256 i = 0; i < length; i++) {
            if (
                Strings.equal(addresses[i].addressType, canonical.addressType) &&
                Strings.equal(addresses[i].value, canonical.value)
            ) {
                addresses[i] = addresses[length - 1];
                addresses.pop();
                break;
            }
        }
        delete _addressToTokenId[canonical.addressType][canonical.value];

        emit AgentAddressRemoved(tokenId, canonical.addressType, canonical.value);
    }

    /// @dev Propose to add or update an image for a token. (used if moderators setup)
    /// @param tokenId The token affected by the proposal.
    /// @param image The key/value pair representing the image.
    function createAddOrUpdateAgentImageProposal(
        uint256 tokenId,
        KeyValue memory image
    ) external onlyWhenModeratorsExist onlyAgentControllerOrModerator(tokenId) {
        bytes32 keyHash = keccak256(bytes(image.key));
        uint256 existingProposalId = _imageProposalIdByTokenAndKey[tokenId][keyHash];

        if (existingProposalId != 0) {
            uint256 existingIndex = _imageProposalIndexOf(existingProposalId);
            _addOrUpdateAgentImageProposals[existingIndex].image = image;
            return;
        }

        _addOrUpdateAgentImageProposals.push(AddOrUpdateAgentImageProposal({
            id: _nextProposalId,
            tokenId: tokenId,
            image: image
        }));

        _addOrUpdateAgentImageProposalIndexById[_nextProposalId] = _addOrUpdateAgentImageProposals.length;
        _imageProposalIdByTokenAndKey[tokenId][keyHash] = _nextProposalId;

        emit AgentImageProposalCreated(
            tokenId,
            image.key,
            _nextProposalId
        );

        _nextProposalId++;
    }

    /// @dev Add or update an image for a token. (allowed when no moderators are
    /// setup or the caller is a moderator)
    /// @param tokenId The token affected.
    /// @param image The key/value pair representing the image.
    function addOrUpdateAgentImage(
        uint256 tokenId,
        KeyValue memory image
    ) external onlyWhenNoModeratorsOrSenderIsModerator onlyAgentControllerOrModerator(tokenId) {
        _addOrUpdateAgentImage(
            tokenId,
            image
        );
    }

    /// @dev Apply an image proposal.
    /// @param proposalId The id of the proposal to apply.
    function addOrUpdateAgentImageFromProposal(
        uint256 proposalId
    ) external onlyRole(MODERATOR_ROLE) {
        uint256 proposalIndex = _imageProposalIndexOf(proposalId);
        AddOrUpdateAgentImageProposal memory proposalInfo = _addOrUpdateAgentImageProposals[proposalIndex];

        _addOrUpdateAgentImage(
            proposalInfo.tokenId,
            proposalInfo.image
        );

        _popAddOrUpdateAgentImageProposalAt(proposalId);
    }

    function _addOrUpdateAgentImage(
        uint256 tokenId,
        KeyValue memory image
    ) internal {
        AgentInformation storage agentInformation = _agentInformationOf[tokenId];

        string memory oldValue = agentInformation.images.addOrUpdate(image.key, image.value);

        emit AgentImageUpdated(
            tokenId,
            image.key,
            oldValue,
            image.value
        );
    }

    /// @dev Refuse an image proposal.
    /// @param proposalId The id of the proposal to refuse.
    function refuseAddOrUpdateAgentImageProposal(
        uint256 proposalId
    ) external onlyRole(MODERATOR_ROLE) {
        _popAddOrUpdateAgentImageProposalAt(proposalId);
    }

    /// @dev Remove an image from a token.
    /// @param tokenId The token whose image is removed.
    /// @param key The key of the image to remove.
    function removeAgentImage(
        uint256 tokenId,
        string memory key
    ) external onlyAgentControllerOrModerator(tokenId) {
        KeyValue[] storage images = _agentInformationOf[tokenId].images;
        images.remove(key);

        if (!images.containKey("default")) {
            revert MissingDefaultImage();
        }
    }

    /// @dev Propose minting of a new agent token. (used if moderators setup)
    /// @param to The future owner of the token.
    /// @param role The agent role.
    /// @param name The Name of the agent.
    /// @param addresses Typed addresses controlled by the agent (at least one evm).
    /// @param images A set of images describing the agent.
    /// @param attributes A set of attributes describing the agent.
    /// @param cloneOf The ID of the agent to clone (if any).
    function createMintProposal(
        address to,
        string memory role,
        string memory name,
        AgentAddress[] memory addresses,
        KeyValue[] memory images,
        KeyValue[] memory attributes,
        NullableUint256 memory cloneOf
    ) external onlyWhenModeratorsExist {
        AgentAddress[] memory canonical = addresses.canonicalizeAndRequireEvm();
        _validateMintInputs(to, name, canonical, images, cloneOf);

        _mintProposals.push(MintProposal({
            id: _nextProposalId,
            name: name,
            role: role,
            owner: to,
            images: images,
            cloneOf: cloneOf,
            addresses: canonical,
            creator: _msgSender(),
            attributes: attributes
        }));

        _mintProposalIndexById[_nextProposalId] = _mintProposals.length;

        emit MintProposalCreated(to, _nextProposalId);

        _nextProposalId++;
    }

    /// @dev Mint a new agent token. (allowed when no moderators are setup or
    /// the caller is a moderator)
    /// @param to The future owner of the token.
    /// @param role The agent role.
    /// @param name The Name of the agent.
    /// @param addresses Typed addresses controlled by the agent (at least one evm).
    /// @param images A set of images describing the agent.
    /// @param attributes A set of attributes describing the agent.
    /// @param cloneOf The ID of the agent to clone (if any).
    function mint(
        address to,
        string memory role,
        string memory name,
        AgentAddress[] memory addresses,
        KeyValue[] memory images,
        KeyValue[] memory attributes,
        NullableUint256 memory cloneOf
    ) external onlyWhenNoModeratorsOrSenderIsModerator {
        AgentAddress[] memory canonical = addresses.canonicalizeAndRequireEvm();
        _validateMintInputs(to, name, canonical, images, cloneOf);
        _mintAgent(to, _msgSender(), role, name, canonical, images, attributes, cloneOf);
    }

    /// @dev Mint an agent from an approved proposal.
    /// @param proposalId The id of the mint proposal to execute.
    function mintFromProposal(
        uint256 proposalId
    ) external onlyRole(MODERATOR_ROLE) {
        uint256 proposalIndex = _mintProposalIndexOf(proposalId);
        MintProposal memory proposalInfo = _mintProposals[proposalIndex];

        _requireUniqueNameAndUniqueAddresses(proposalInfo.name, proposalInfo.addresses);

        _mintAgent(
            proposalInfo.owner,
            proposalInfo.creator,
            proposalInfo.role,
            proposalInfo.name,
            proposalInfo.addresses,
            proposalInfo.images,
            proposalInfo.attributes,
            proposalInfo.cloneOf
        );
        _popMintProposalAt(proposalId);
    }

    /// @dev Internal function to validate minting parameters (addresses must already be canonical).
    function _validateMintInputs(
        address to,
        string memory name,
        AgentAddress[] memory addresses,
        KeyValue[] memory images,
        NullableUint256 memory cloneOf
    ) internal view {
        if (to == address(0)) {
            revert ZeroAddress("to");
        }
        if (!ENSUtils.isValidENSName(name)) {
            revert InvalidName(name);
        }

        _requireUniqueNameAndUniqueAddresses(name, addresses);

        if (!images.containKey("default")) {
            revert MissingDefaultImage();
        }
        if (cloneOf.isSet && (cloneOf.value == 0 || cloneOf.value >= nextTokenId)) {
            revert InvalidCloneOf(cloneOf.value);
        }
    }

    /// @dev Internal function to mint an agent NFT and store its information (addresses must already be canonical).
    function _mintAgent(
        address to,
        address creator,
        string memory role,
        string memory name,
        AgentAddress[] memory addresses,
        KeyValue[] memory images,
        KeyValue[] memory attributes,
        NullableUint256 memory cloneOf
    ) internal {
        uint256 tokenId = nextTokenId;

        _agentInformationOf[tokenId] = AgentInformation({
            name: name,
            role: role,
            images: images,
            addresses: addresses,
            creator: creator,
            cloneOf: cloneOf,
            attributes: attributes
        });
        _nameToTokenId[name] = tokenId;
        for (uint256 i = 0; i < addresses.length; i++) {
            _addressToTokenId[addresses[i].addressType][addresses[i].value] = tokenId;
        }
        nextTokenId = tokenId + 1;

        _safeMint(to, tokenId);
        emit Minted(to, tokenId);
    }

    /// @dev Refuse a mint proposal.
    /// @param proposalId The id of the proposal to refuse.
    function refuseMintProposal(
        uint256 proposalId
    ) external onlyRole(MODERATOR_ROLE) {
        _popMintProposalAt(proposalId);
    }

    function _popAddOrUpdateAgentImageProposalAt(uint256 proposalId) private {
        uint256 index = _imageProposalIndexOf(proposalId);

        AddOrUpdateAgentImageProposal memory proposal = _addOrUpdateAgentImageProposals[index];
        uint256 lastIndex = _addOrUpdateAgentImageProposals.length - 1;
        if (index != lastIndex) {
            _addOrUpdateAgentImageProposals[index] = _addOrUpdateAgentImageProposals[lastIndex];
            _addOrUpdateAgentImageProposalIndexById[_addOrUpdateAgentImageProposals[index].id] = index + 1;
        }
        _addOrUpdateAgentImageProposals.pop();
        delete _addOrUpdateAgentImageProposalIndexById[proposalId];
        delete _imageProposalIdByTokenAndKey[proposal.tokenId][keccak256(bytes(proposal.image.key))];

        emit AgentImageProposalRemoved(
            proposal.tokenId,
            proposal.image.key,
            proposalId
        );
    }

    function _popMintProposalAt(uint256 proposalId) private {
        uint256 index = _mintProposalIndexOf(proposalId);

        MintProposal memory proposal = _mintProposals[index];
        uint256 lastIndex = _mintProposals.length - 1;
        if (index != lastIndex) {
            _mintProposals[index] = _mintProposals[lastIndex];
            _mintProposalIndexById[_mintProposals[index].id] = index + 1;
        }
        _mintProposals.pop();
        delete _mintProposalIndexById[proposalId];

        emit MintProposalRemoved(proposal.owner, proposalId);
    }

    /// @dev Resolves a mint proposal id to its array index, reverting if none exists.
    function _mintProposalIndexOf(uint256 proposalId) private view returns (uint256) {
        uint256 stored = _mintProposalIndexById[proposalId];
        if (stored == 0) {
            revert ProposalNotFound(proposalId);
        }
        return stored - 1;
    }

    /// @dev Resolves an image proposal id to its array index, reverting if none exists.
    function _imageProposalIndexOf(uint256 proposalId) private view returns (uint256) {
        uint256 stored = _addOrUpdateAgentImageProposalIndexById[proposalId];
        if (stored == 0) {
            revert ProposalNotFound(proposalId);
        }
        return stored - 1;
    }

    /// @dev Returns true if `account` owns the agent NFT or is one of its evm addresses.
    function _isAgentController(uint256 tokenId, address account) internal view returns (bool) {
        return ownerOf(tokenId) == account ||
            _addressToTokenId[EVM_TYPE][Strings.toHexString(account)] == tokenId;
    }

    /// @dev Reverts if the name or any canonical address is already used, or the list repeats an address.
    function _requireUniqueNameAndUniqueAddresses(
        string memory name,
        AgentAddress[] memory addresses
    ) internal view {
        uint256 tokenIdForName = _nameToTokenId[name];
        if (tokenIdForName != 0) {
            revert UsedName(name, tokenIdForName);
        }
        for (uint256 i = 0; i < addresses.length; i++) {
            uint256 tokenIdForAddress = _addressToTokenId[addresses[i].addressType][addresses[i].value];
            if (tokenIdForAddress != 0) {
                revert UsedAgentAddress(addresses[i].addressType, addresses[i].value, tokenIdForAddress);
            }
            for (uint256 j = 0; j < i; j++) {
                if (
                    Strings.equal(addresses[j].addressType, addresses[i].addressType) &&
                    Strings.equal(addresses[j].value, addresses[i].value)
                ) {
                    revert UsedAgentAddress(addresses[i].addressType, addresses[i].value, 0);
                }
            }
        }
    }

    /// @dev Reverts if the `tokenId` doesn't have a current owner
    /// (it hasn't been minted or it has been burned).
    function _requireMinted(uint256 tokenId) internal view returns (address) {
        if (tokenId == 0 || tokenId >= nextTokenId) {
            revert ERC721NonexistentToken(tokenId);
        }
        return _ownerOf(tokenId);
    }
}

