// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.28;

import {KeyValue} from "../../types/KeyValue.sol";
import {AgentAddress} from "../../types/AgentAddress.sol";

interface IAgentCollectionStates {
    /// @dev Get the fact that a account is a moderator or not.
    function isModerator(address account) external view returns (bool);

    /// @dev Number of moderators configured on the collection.
    function moderatorCount() external view returns (uint256);

    /// @dev Get the token ID associated to a typed address, or 0 if none.
    /// @param addressType The type of the address ("evm", "btc", ...).
    /// @param value The address value (evm values accepted in any casing).
    function addressToTokenId(string memory addressType, string memory value) external view returns (uint256);

    /// @dev The next tokenId to be minted (count of minted agents + 1).
    function nextTokenId() external view returns (uint256);

    /// @dev Description of the collection.
    function description() external view returns (string memory);

    /// @dev Get the name of an agent.
    /// @param tokenId The token identifier.
    function nameOf(uint256 tokenId) external view returns (string memory);

    /// @dev Get the role of an agent
    /// @param tokenId The token identifier.
    function roleOf(uint256 tokenId) external view returns (string memory);

    /// @dev Get the number of images of an agent.
    /// @param tokenId The token identifier.
    function imagesCountOf(uint256 tokenId) external view returns (uint256);

    /// @dev Get a specific image of an agent by its index.
    /// @param tokenId The token identifier.
    /// @param index The index of the image.
    function imageOfByIndex(uint256 tokenId, uint256 index) external view returns (KeyValue memory);

    /// @dev Get the number of typed addresses of an agent.
    /// @param tokenId The token identifier.
    function addressesCountOf(uint256 tokenId) external view returns (uint256);

    /// @dev Get a specific typed address of an agent by its index.
    /// @param tokenId The token identifier.
    /// @param index The index of the address.
    function addressOfByIndex(uint256 tokenId, uint256 index) external view returns (AgentAddress memory);
}

contracts/interfaces/IAgentCollectionCre.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.28;

import {IAgentCollectionCreatorV1Events} from "./IAgentCollectionCreatorV1Events.sol";
import {IAgentCollectionCreatorV1OwnerActions} from "./IAgentCollectionCreatorV1OwnerActions.sol";
import {IAgentCollectionCreatorV1Actions} from "./IAgentCollectionCreatorV1Actions.sol";
import {IAgentCollectionCreatorV1States} from "./IAgentCollectionCreatorV1States.sol";

interface IAgentCollectionCreatorV1 is
    IAgentCollectionCreatorV1Events,
    IAgentCollectionCreatorV1States,
    IAgentCollectionCreatorV1Actions,
    IAgentCollectionCreatorV1OwnerActions {

}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.28;

interface IAgentCollectionCreatorV1Actions {
    /// @dev Create a new agent collection contract.
    /// @param name Name of the collection.
    /// @param symbol Symbol of the collection.
    /// @param description Description of the collection.
    /// @param admin Admin address for the collection.
    /// @param moderator Moderator address for the collection.
    /// @return collectionAddress Address of the newly created collection.
    function createCollection(
        string memory name,
        string memory symbol,
        string memory description,
        address admin,
        address moderator
    ) external returns (address collectionAddress);
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.28;

interface IAgentCollectionCreatorV1Events {
    /// @dev Emitted when the collections descriptor is updated.
    /// @param oldDescriptor The address of the old collections descriptor.
    /// @param newDescriptor The address of the new collections descriptor.
    event DefaultCollectionsDescriptorUpdated(address oldDescriptor, address newDescriptor);
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.28;

interface IAgentCollectionCreatorV1OwnerActions {
    /// @dev Update the default collections descriptor.
    /// @param newDescriptor The new default descriptor for the new collections.
    function updateCollectionsDescriptor(address newDescriptor) external;
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.28;

interface IAgentCollectionCreatorV1States {
    /// @dev Get the default collections descriptor.
    /// @return Address of the default collections descriptor.
    function collectionsDescriptor() external view returns (address);
}

